const { chromium } = require("/home/pixel/.cache/ms-playwright-go/1.57.0/package");

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on("console", (m) => m.type() === "error" && errors.push(m.text()));
  page.on("pageerror", (e) => errors.push(String(e)));

  await page.goto("http://localhost:3000", { waitUntil: "networkidle" });
  await page.getByRole("button", { name: /Map my audience/ }).click();
  await page.waitForSelector("text=Competitors", { timeout: 30000 });
  await page.getByRole("tab", { name: "Competitors" }).click().catch(async () => {
    await page.getByRole("button", { name: "Competitors" }).click();
  });
  await page.waitForTimeout(6000);

  const logos = await page.evaluate(() =>
    [...document.querySelectorAll("aside img")].map((img) => ({
      src: img.getAttribute("src"),
      loaded: img.complete && img.naturalWidth > 0,
      box: img.getBoundingClientRect().toJSON(),
    })),
  );
  const markers = await page.evaluate(() =>
    [...document.querySelectorAll(".maplibregl-canvas-container img")].map((img) => ({
      src: img.getAttribute("src"),
      loaded: img.complete && img.naturalWidth > 0,
    })),
  );
  await page.screenshot({ path: "/tmp/opencode/competitors.png" });
  await page.screenshot({ path: "/tmp/opencode/map.png", clip: { x: 0, y: 0, width: 950, height: 900 } });
  console.log(JSON.stringify({ logos: logos.slice(0, 6), markers, errors }, null, 1));
  await browser.close();
})();

